<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/economy.php';
$me=require_owner(); $users=data_load('users.json');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['user_id'];$action=$_POST['action']??'';$items=data_load('subscriptions.json');if($action==='remove'){foreach($items as &$s)if((int)$s['user_id']===$id)$s['status']='revoked';unset($s);log_action('premium_remove','user:'.$id);}elseif($action==='give'){ $days=(int)$_POST['days'];$days=max(1,min(3650,$days));$items[]=['id'=>next_id($items),'user_id'=>$id,'plan'=>'premium','status'=>'active','issued_by'=>$me['id'],'issued_at'=>date('c'),'expires_at'=>date('c',time()+$days*86400)];log_action('premium_give','user:'.$id,$days.' days');}data_save('subscriptions.json',$items);header('Location: subscriptions.php');exit;}
include __DIR__.'/../includes/header.php'; ?><section class="card"><h1>⭐ Premium</h1><p>Выдача и снятие Premium доступна только владельцу форума.</p></section><?php foreach($users as $u): $s=subscription($u); ?><form method="post" class="card" style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><b><?=e($u['username'])?></b><span><?= $s?'⭐ Premium':'Обычный аккаунт' ?></span><?php if($s): ?><button class="btn" name="action" value="remove">Снять</button><?php else: ?><input type="number" name="days" value="30" min="1" max="3650"><button class="btn" name="action" value="give">Выдать</button><?php endif; ?></form><?php endforeach; ?><?php include __DIR__.'/../includes/footer.php'; ?>